using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this application.");

var services = new ServiceCollection();

services.AddChatClient(builder => builder
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

var serviceProvider = services.BuildServiceProvider();
var chatClient = serviceProvider.GetRequiredService<IChatClient>();

// Define tools available to the research agent
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the web_search tool
        2. Saving important findings as notes using the save_note tool
        3. Reviewing your collected notes using the get_notes tool
        4. Providing a comprehensive summary of your findings

        Always perform multiple searches to cover different aspects of the topic.
        Save key findings as you go so you can reference them in your final summary.
        End with a well-structured summary that synthesizes all your research.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes",
    tools: tools);

// Get the research topic from the user
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0.2f,
        MaxOutputTokens = 4096,
    },
};

await foreach (var update in agent.RunStreamingAsync(messages, session, runOptions))
{
    Console.Write(update.Text);
}

Console.WriteLine("\n\n✅ Research complete.");

// --- Tool implementations ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns search results as text.")]
static string WebSearch([Description("The search query to look up")] string query)
{
    // Simulated web search - in production, integrate with a real search API (e.g., Bing Search)
    Console.WriteLine($"  🌐 Searching: \"{query}\"");
    return $"""
        Search results for "{query}":

        1. [Wikipedia] {query} - A comprehensive overview covering the main concepts, 
           history, and current state of {query}. Key points include recent developments 
           and notable contributions to the field.

        2. [Research Paper] "Advances in {query}" (2025) - Recent peer-reviewed research 
           highlighting breakthroughs and challenges. Discusses future directions and 
           potential applications.

        3. [News Article] "{query}: What You Need to Know in 2026" - Current trends, 
           industry adoption, and expert opinions on where {query} is headed.

        4. [Technical Blog] "Deep Dive into {query}" - Practical guide with examples, 
           best practices, and common pitfalls to avoid when working with {query}.
        """;
}

[Description("Save a research note for later reference. Use this to record important findings.")]
string SaveNote(
    [Description("A short title for the note")] string title,
    [Description("The content of the note")] string content)
{
    notes.Add($"[{title}]: {content}");
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
    return $"Note saved: {title}";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  📋 Reviewing {notes.Count} note(s)");
    return string.Join("\n\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

